import {validate,solve,timeLabel,actions} from './engine.mjs';
const $=s=>document.querySelector(s);let lastModel=null,lastResult=null,worker=null,revision=0;
const sample=[{name:'Dish A · main',temp:350,duration:100,slots:2,rest:40,early:55},{name:'Dish B · side',temp:375,duration:25,slots:1,rest:0,early:10},{name:'Dish C · side',temp:375,duration:20,slots:1,rest:0,early:10}];
function el(tag,text,cls){const x=document.createElement(tag);if(text!==undefined)x.textContent=text;if(cls)x.className=cls;return x;}
function field(label,key,value,min,max){const l=el('label',label);const input=document.createElement('input');input.type=key==='name'?'text':'number';input.dataset.key=key;input.value=value;if(key==='name')input.maxLength=80;else{input.min=min;input.max=max;input.step=key==='temp'?'any':'1';}l.append(input);return l;}
function addDish(d={name:'',temp:$('#unit').value==='F'?350:175,duration:30,slots:1,rest:0,early:0}){
 const card=el('div',undefined,'dish');const top=el('div',undefined,'dish-top');top.append(el('span','', 'dish-number'));const name=field('Dish name','name',d.name);name.className='dish-name';top.append(name);const remove=el('button','Remove','remove');remove.type='button';remove.onclick=()=>{card.remove();recount();dirty();};top.append(remove);card.append(top);
 const fields=el('div',undefined,'dish-fields');const unit=$('#unit').value;fields.append(field(`Oven setting (°${unit})`,'temp',d.temp,unit==='F'?32:0,unit==='F'?752:400),field('Oven time (min)','duration',d.duration,1,720),field('Pan slots used','slots',d.slots,1,6));
 const set=el('fieldset');set.append(el('legend','Finish before serving (min)'));const win=el('div',undefined,'window');win.append(field('Minimum / rest','rest',d.rest,0,360),field('Maximum / earliest','early',d.early,0,360));set.append(win);fields.append(set);card.append(fields);$('#dishes').append(card);recount();return card;
}
function recount(){const list=[...document.querySelectorAll('.dish')];list.forEach((c,i)=>{c.querySelector('.dish-number').textContent=String(i+1).padStart(2,'0');c.querySelector('.remove').setAttribute('aria-label',`Remove dish ${i+1}`);});$('#dish-count').textContent=`${list.length} / 6`;$('#add').disabled=list.length>=6;}
function model(){const [h,min]=$('#serve').value.split(':').map(Number);return {serve:h*60+min,unit:$('#unit').value,capacity:Number($('#capacity').value),buffer:$('#buffer').value===''?NaN:Number($('#buffer').value),dishes:[...document.querySelectorAll('.dish')].map(c=>Object.fromEntries([...c.querySelectorAll('input')].map(i=>[i.dataset.key,i.dataset.key==='name'?i.value.trim():i.value===''?NaN:Number(i.value)])))};}
function dirty(){revision++;if(worker){worker.terminate();worker=null;}$('#check').disabled=false;$('#check').textContent='Check my oven plan →';$('#print').disabled=true;if(!$('#stale')){const b=el('div','Inputs changed. Check the plan again before using or printing it.','stale');b.id='stale';$('#result-body').prepend(b);}$('#sample-note').textContent='Use your own tested recipe instructions. Finish windows are not food-safety limits.';}
function render(result,m){lastResult=result;lastModel=m;const box=$('#result-body');box.replaceChildren();$('#result-kicker').textContent='YOUR OVEN CHECK';$('#print').disabled=result.status!=='ok';
 if(result.status==='invalid'){$('#result-title').textContent='Check these inputs';const ul=el('ul',undefined,'error-list');result.errors.forEach(e=>ul.append(el('li',e)));box.append(ul);return;}
 if(result.status!=='ok'){$('#result-title').textContent=result.status==='unknown'?'No answer yet':'These inputs conflict';box.append(el('p',result.reason,'status'));box.append(el('p','Try a recipe-supported wider finish window, correct the measured pan space, or take a dish off this oven plan. Do not change cooking temperatures or safe handling just to make a timeline fit.','status'));return;}
 $('#result-title').textContent='A matching schedule';const note=el('p','Fits the entered timing, temperature and space constraints. It is a planning estimate, not a cooking or safety guarantee.','status');box.append(note);
 const meta=el('div',undefined,'result-meta');meta.append(el('span',`Serve · ${timeLabel(m.serve)}`),el('span',`Capacity · ${m.capacity} slots`),el('span',`Heat buffer · ${m.buffer} min`),el('span',`${m.dishes.length} dishes · °${m.unit}`));box.append(meta);
 const list=el('ol',undefined,'timeline');for(const action of actions(result.items,m)){const li=el('li');li.append(el('time',timeLabel(action.time)),el('span',action.text));list.append(li);}box.append(list);
 const windows=el('p',`Entered finish windows: ${m.dishes.map(d=>`${d.name}: ${d.rest}–${d.early} min before serving`).join('; ')}.`,'plan-foot');box.append(windows,el('p','One fixed temperature per dish. Exact temperature matches may share measured slots. Prep, safe holding, loading and oven recovery are not verified. Keep the original recipes beside this sheet.','plan-foot'));
}
function check(focus=true){const m=model();const e=validate(m);if(e.length){render({status:'invalid',errors:e},m);if(focus)$('#results').focus();return;}if(worker)worker.terminate();const version=revision;$('#check').disabled=true;$('#check').textContent='Checking…';$('#print').disabled=true;
 const finish=r=>{if(version!==revision)return;$('#check').disabled=false;$('#check').textContent='Check my oven plan →';render(r,m);if(focus)$('#results').focus();};
 if(typeof Worker!=='undefined'){try{worker=new Worker('./worker.mjs',{type:'module'});worker.onmessage=({data})=>{worker.terminate();worker=null;finish(data);};worker.onerror=()=>{worker.terminate();worker=null;finish(solve(m,30000));};worker.postMessage(m);}catch{finish(solve(m,30000));}}else finish(solve(m,30000));}
$('#plan-form').addEventListener('submit',e=>{e.preventDefault();check();});$('#plan-form').addEventListener('input',e=>{if(e.target.dataset.key==='temp'){delete e.target.dataset.originValue;delete e.target.dataset.originUnit;}dirty();});$('#capacity').addEventListener('change',dirty);
let prevUnit='F';$('#unit').addEventListener('change',()=>{const unit=$('#unit').value;const origins=[...document.querySelectorAll('[data-key="temp"]')].map(input=>({value:input.dataset.originValue??input.value,unit:input.dataset.originUnit??prevUnit}));const dishes=model().dishes.map((d,i)=>({...d,temp:origins[i].value===''?'':origins[i].unit===unit?Number(origins[i].value):Math.round((origins[i].unit==='F'?(Number(origins[i].value)-32)*5/9:Number(origins[i].value)*9/5+32)*100)/100}));prevUnit=unit;$('#dishes').replaceChildren();dishes.forEach((d,i)=>{const card=addDish(d);const input=card.querySelector('[data-key="temp"]');input.dataset.originValue=origins[i].value;input.dataset.originUnit=origins[i].unit;});dirty();$('#sample-note').textContent='Converted temperatures are rounded to two decimals. Returning to the original unit restores your original setting. Check settings against your recipe.';});
$('#add').onclick=()=>{if(document.querySelectorAll('.dish').length>=6)return;const card=addDish();dirty();card.querySelector('input').focus();};
$('#sample').onclick=()=>{if(worker)worker.terminate();worker=null;revision++;$('#serve').value='17:00';$('#capacity').value='2';$('#buffer').value='15';$('#unit').value='F';prevUnit='F';$('#dishes').replaceChildren();sample.forEach(addDish);$('#sample-note').textContent='Illustrative scheduling numbers only. These are not recipes or tested cooking instructions.';check(false);};
$('#print').onclick=()=>{if(lastResult?.status==='ok'&&!$('#stale'))window.print();};sample.forEach(addDish);check(false);
